// Attach the n8n context LangSmith does not send on its own.
//
// The proxy routes to a Langfuse project on metadata.node (or a "node:<name>"
// tag) and groups traces into a Session on metadata.session_id. Neither is
// something n8n injects, so a workflow that wants per-project routing, a real
// chat session or a user attribution has to set them here, on the run config.

const { ChatPromptTemplate } = require('@langchain/core/prompts');
const { StringOutputParser } = require('@langchain/core/output_parsers');

const item = $input.first().json;

const question  = item.question   || 'What is the weather in Kochi today?';
const sessionId = item.session_id || 'chat-session-001';
const userId    = item.user_id    || 'subin';

const llm = await this.getInputConnectionData('ai_languageModel', 0);

const prompt = ChatPromptTemplate.fromMessages([
  ['system', 'You are a concise weather assistant. Answer in one sentence.'],
  ['human', '{question}'],
]);

const chain = prompt.pipe(llm).pipe(new StringOutputParser()).withConfig({
  runName: 'CRM Weather Chain',
  tags: ['node:crm'],
  metadata: {
    node: 'crm',
    session_id: sessionId,
    user_id: userId,
    workflow_name: 'CRM Weather Agent',
  },
});

const output = await chain.invoke({ question });

return [{ json: { output, session_id: sessionId, user_id: userId } }];
